<?php get_header(); while (have_posts()) : the_post(); $id = get_the_ID(); ?>
<div class="container"><?php fp_theme_breadcrumb('Réalisations', home_url('/realisations/')); ?></div>
<section class="page-intro container"><p class="eyebrow"><?php echo esc_html(get_post_meta($id, 'town', true)); ?></p><h1><?php the_title(); ?></h1><p class="intro-copy"><?php echo esc_html(get_post_meta($id, 'short_description', true)); ?></p></section>
<div class="container project-detail"><?php if (has_post_thumbnail()) { the_post_thumbnail('fp-project-wide', array('class' => 'project-cover', 'loading' => 'eager')); } ?><div class="detail-layout"><article class="prose"><?php the_content(); ?></article><aside class="project-aside"><p class="eyebrow">Le chantier</p><dl><dt>Commune</dt><dd><?php echo esc_html(get_post_meta($id, 'town', true)); ?></dd><?php $service = absint(get_post_meta($id, 'service', true)); if ($service && get_post_status($service) === 'publish' && function_exists('fp_public_content_allowed') && fp_public_content_allowed(get_post($service))) : ?><dt>Prestation</dt><dd><a href="<?php echo esc_url(get_permalink($service)); ?>"><?php echo esc_html(get_the_title($service)); ?></a></dd><?php endif; ?></dl><?php fp_theme_quote_button('Demander un rendez-vous'); ?></aside></div>
<?php $before = function_exists('fp_image_id') ? fp_image_id($id, 'before_photo') : 0; $after = function_exists('fp_image_id') ? fp_image_id($id, 'after_photo') : 0; if ($before && $after) : ?><section class="before-after"><h2>Avant et après</h2><div class="before-after-grid"><figure><?php echo wp_get_attachment_image($before, 'fp-project'); ?><figcaption>Avant les travaux</figcaption></figure><figure><?php echo wp_get_attachment_image($after, 'fp-project'); ?><figcaption>Après les travaux</figcaption></figure></div></section><?php endif; ?>
<?php $gallery = function_exists('fp_gallery') ? fp_gallery($id) : array(); if ($gallery) : ?><section class="project-gallery" aria-label="Photographies du chantier"><?php foreach ($gallery as $photo) : ?><figure><?php echo wp_get_attachment_image(absint($photo), 'fp-project-wide', false, array('loading' => 'lazy')); ?><?php $caption = wp_get_attachment_caption(absint($photo)); if ($caption) : ?><figcaption><?php echo esc_html($caption); ?></figcaption><?php endif; ?></figure><?php endforeach; ?></section><?php endif; ?>
</div>
<?php endwhile; fp_theme_contact_band(); get_footer(); ?>
